begin;
drop policy if exists "ccwu_cinema_posters_public_read" on storage.objects;
create policy "ccwu_cinema_posters_public_read" on storage.objects as PERMISSIVE for SELECT to anon, authenticated using ((bucket_id = 'ccwu-cinema-posters'::text));
drop policy if exists "ccwu_cinema_staff_read_private_media" on storage.objects;
create policy "ccwu_cinema_staff_read_private_media" on storage.objects as PERMISSIVE for SELECT to authenticated using (((bucket_id = ANY (ARRAY['ccwu-cinema-videos'::text, 'ccwu-cinema-subtitles'::text])) AND is_ccwu_admin()));
drop policy if exists "ccwu_cinema_staff_upload_media" on storage.objects;
create policy "ccwu_cinema_staff_upload_media" on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = ANY (ARRAY['ccwu-cinema-posters'::text, 'ccwu-cinema-videos'::text, 'ccwu-cinema-subtitles'::text])) AND is_ccwu_admin()));
drop policy if exists "customer or staff reads payment proof" on storage.objects;
create policy "customer or staff reads payment proof" on storage.objects as PERMISSIVE for SELECT to authenticated using (((bucket_id = 'ccwu-payment-proofs'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR is_ccwu_admin())));
drop policy if exists "customers upload own payment proof" on storage.objects;
create policy "customers upload own payment proof" on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = 'ccwu-payment-proofs'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
drop policy if exists "public reads payment QR images" on storage.objects;
create policy "public reads payment QR images" on storage.objects as PERMISSIVE for SELECT to anon, authenticated using ((bucket_id = 'ccwu-payment-qr'::text));
drop policy if exists "staff deletes payment QR images" on storage.objects;
create policy "staff deletes payment QR images" on storage.objects as PERMISSIVE for DELETE to authenticated using (((bucket_id = 'ccwu-payment-qr'::text) AND is_ccwu_admin()));
drop policy if exists "staff updates payment QR images" on storage.objects;
create policy "staff updates payment QR images" on storage.objects as PERMISSIVE for UPDATE to authenticated using (((bucket_id = 'ccwu-payment-qr'::text) AND is_ccwu_admin())) with check (((bucket_id = 'ccwu-payment-qr'::text) AND is_ccwu_admin()));
drop policy if exists "staff uploads payment QR images" on storage.objects;
create policy "staff uploads payment QR images" on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = 'ccwu-payment-qr'::text) AND is_ccwu_admin()));
commit;
